WHERE s.deleted=0 
    AND (h.shipment_no LIKE CONCAT('%',#{query.keyword},'%') OR h.tracking_no LIKE CONCAT('%',#{query.keyword},'%') OR s.order_no LIKE CONCAT('%',#{query.keyword},'%') OR c.company_name LIKE CONCAT('%',#{query.keyword},'%'))
    AND h.status=#{query.status}
